                for m in matches:
                    expected = p.parse(TextSlice(text, *m.range))
                    self.assertEqual(m.value, expected)
                    self.assertEqual(vars(m.value.meta), vars(expected.meta))
                    self.assertEqual(m.value.children[0].line, 2)

